method CanyonSearch(a: seq<int>, b: seq<int>) returns (result: nat)
  requires |a| > 0 && |b| > 0
  requires forall i, j :: 0 <= i < j < |a| ==> a[i] <= a[j]
  requires forall i, j :: 0 <= i < j < |b| ==> b[i] <= b[j]
  ensures DistanceOccursFrom(a, b, result, 0)
  ensures forall i, j :: 0 <= i < |a| && 0 <= j < |b| ==> result <= Abs(a[i] - b[j])
{
  var d := Abs(a[0] - b[0]);
  var wi, wj := 0, 0;
  var i := 0;
  while i < |a|
    invariant 0 <= i <= |a|
    invariant 0 <= wi < |a| && 0 <= wj < |b| && d == Abs(a[wi] - b[wj])
    invariant forall p, q :: 0 <= p < i && 0 <= q < |b| ==> d <= Abs(a[p] - b[q])
  {
    var j := 0;
    while j < |b|
      invariant 0 <= j <= |b|
      invariant 0 <= wi < |a| && 0 <= wj < |b| && d == Abs(a[wi] - b[wj])
      invariant forall p, q :: 0 <= p < i && 0 <= q < |b| ==> d <= Abs(a[p] - b[q])
      invariant forall q :: 0 <= q < j ==> d <= Abs(a[i] - b[q])
    {
      if Abs(a[i] - b[j]) < d {
        d := Abs(a[i] - b[j]);
        wi, wj := i, j;
      }
      j := j + 1;
    }
    i := i + 1;
  }
  WitnessOccurs(a, b, d, wi, wj, 0);
  result := d;
}

lemma WitnessOccurs(a: seq<int>, b: seq<int>, d: nat, wi: nat, wj: nat, i: nat)
  requires i <= wi < |a| && wj < |b| && Abs(a[wi] - b[wj]) == d
  ensures DistanceOccursFrom(a, b, d, i)
  decreases wi - i
{
  if i < wi {
    WitnessOccurs(a, b, d, wi, wj, i + 1);
  } else {
    assert b[wj] == a[wi] - d || b[wj] == a[wi] + d;
    assert b[wj] in b;
  }
}

