import icontract
from typing import List


@icontract.require(lambda a, b: len(a) > 0 and len(b) > 0)
@icontract.require(lambda a: all(a[i] <= a[i + 1] for i in range(len(a) - 1)))
@icontract.require(lambda b: all(b[i] <= b[i + 1] for i in range(len(b) - 1)))
@icontract.ensure(lambda result: result >= 0)
@icontract.ensure(lambda a, b, result: any(result == abs(x - y) for x in a for y in b))
@icontract.ensure(lambda a, b, result: all(result <= abs(x - y) for x in a for y in b))
def CanyonSearch(a: List[int], b: List[int]) -> int:
    m, n = 0, 0
    d = abs(a[0] - b[0])
    while m < len(a) and n < len(b):
        t = abs(a[m] - b[n])
        if t < d:
            d = t
        if a[m] <= b[n]:
            m += 1
        else:
            n += 1
    return d
